class Solution:
    def haveConflict(self, event1: List[str], event2: List[str]) -> bool:
        def to_min(t: str) -> int:
            h, m = t.split(':')
            return int(h) * 60 + int(m)
        s1, e1 = to_min(event1[0]), to_min(event1[1])
        s2, e2 = to_min(event2[0]), to_min(event2[1])
        return max(s1, s2) <= min(e1, e2)

